void main() {
  stdout.write('Enter the name of a city (e.g., "Los Angeles"): ');
  String? input = stdin.readLineSync();

  if (input == null || input.isEmpty) {
    print('No input provided. Exiting.');
    return;
  }

  var parts = input.trim().split(' ').toList();


  switch (parts.length) {
    case 1:
      _processSingleWord(parts[0]);
      break;
    case 2:
      _processTwoWords(parts[0], parts[1]);
      break;
    default:
      print(
          'Invalid number of words in input. Please provide one or two space-separated words.');
  }
}

void _processSingleWord(String word) {
  List<String> vowels = ['a', 'e', 'i', 'o', 'u'];
  bool hasVowel = false;
  for (char vowel : vowels) {
    if (word.toLowerCase().contains(vowel)) {
      hasVowel = true;
      break;
    }
  }

  if (hasVowel) {
    print('$word starts with a vowel. Plural: ${word + 'es'}');
  } else {
    print('$word does not start with a vowel. Plural: ${word + 's'}');
  }
}

void _processTwoWords(String first, String second) {
  if (_isFirstLetterVowel(first)) {
    print(
        '$first and $second both start with vowels. Plurals: ${_pluralize(first)} and ${_pluralize(second)}.');
  } else {
    print(
        '$first does not start with a vowel. Plural: ${_pluralize(first)}. And $second starts with a vowel. Plural: ${_pluralize(second)}.');
  }
}

bool _isFirstLetterVowel(String word) {
  char lowerCaseChar = word.toLowerCase()[0];
  List<char> vowels = {'a', 'e', 'i', 'o', 'u'};
  return vowels.contains(lowerCaseChar);
}

String _pluralize(String word) {
  if (_isFirstLetterVowel(word)) {
    return word + 'es';
  } else {
    return word + 's';
  }
}

