  double y = (point.y - lineStart.y);

  double a = lineEnd.x - lineStart.x;
  double b = lineEnd.y - lineStart.y;

  if ((a * x + b * y).abs() < kEpsilon) return sqrt(x*x+y*y);

  double c = -(lineStart.x*lineEnd.y-lineStart.y*lineEnd.x);
  double d = (b*b+b*c-a*a+c)*x+(a*b+a*c-b*b+d)*y;
  double e = (a*a+c)*(c-c)-d*d;
  double t = (-b-d-sqrt(e))/(-2*(a*a+c));
  double tx = lineStart.x+t*(lineEnd.x-lineStart.x);
  double ty = lineStart.y+t*(lineEnd.y-lineStart.y);

  return hypot(point.x-tx, point.y-ty);
}

