class Graph {
  final List<List<Edge>> _edges;

  Graph(int vertexCount) : _edges = List.generate(vertexCount, (_) => []);


  void addEdge(Edge edge) {
    _edges[edge.from].add(edge);
  }

  bool hasCycle() {

    List<bool> visited = List.filled(_edges.length, false);
    List<int> pathStack = [];

    for (int i = 0; i < _edges.length; i++) {
      if (!visited[i]) {
        if (_dfs(i, visited, pathStack)) return true;
      }
    }
    return false;
  }

  bool _dfs(int node, List<bool> visited, List<int> pathStack) {
    visited[node] = true;
    pathStack.add(node);

    for (final edge in _edges[node]) {
      int neighbor = edge.to;
      if (!visited[neighbor]) {
        if (_dfs(neighbor, visited, pathStack)) return true;
      } else if (pathStack.contains(neighbor)) {
        return true; 
      }
    }

    pathStack.removeLast();
    return false;
  }
}

